"""Real browser journeys for result interpretation, review, retry and local preferences."""
import json,time
from pathlib import Path
from playwright.sync_api import sync_playwright,expect
OUT=Path(__file__).resolve().parent;BASE='http://127.0.0.1:5173';checks=[]
def check(name,ok):
 checks.append({'name':name,'passed':bool(ok)});print(name,bool(ok),flush=True)
def visit(page,path):page.goto(BASE+path);page.wait_for_load_state('networkidle')
def store(page,key):return page.evaluate('k=>JSON.parse(localStorage.getItem("hm."+k))',key)
def button(page,text):return page.get_by_role('button',name=text,exact=True)
with sync_playwright() as p:
 b=p.chromium.launch(channel='chrome',headless=True);c=b.new_context(viewport={'width':1366,'height':768},timezone_id='Asia/Tashkent')
 c.add_init_script("""window.MutationObserver=class{observe(){}disconnect(){}};const put=Storage.prototype.setItem;Storage.prototype.setItem=function(k,v){if(k===sessionStorage.getItem('fail-key'))throw new DOMException('blocked','QuotaExceededError');return put.call(this,k,v)};const remove=Storage.prototype.removeItem;Storage.prototype.removeItem=function(k){if(k===sessionStorage.getItem('fail-remove'))throw new DOMException('blocked','SecurityError');return remove.call(this,k)}""")
 page=c.new_page();errors=[];page.on('pageerror',lambda e:errors.append(str(e)));visit(page,'/sign-in')
 fixture=page.evaluate("""async()=>{const {TESTS}=await import('/src/data/tests.ts');const {QUESTIONS}=await import('/src/data/questions.ts');const test=TESTS.find(t=>t.id==='practice-1');const qs=test.questionIds.map(id=>QUESTIONS.find(q=>q.id===id));const now=Date.now();const correct=q=>q.kind==='single'?q.correct:q.accepted[0]||'manual';const full=Object.fromEntries(qs.map(q=>[q.id,correct(q)]));const answers={...full};answers[qs[1].id]=qs[1].correct==='A'?'B':'A';delete answers[qs[2].id];answers[qs[3].id]=correct(qs[3])+'x';delete answers[qs[5].id];const make=(id,answers,offset=0)=>({id,testId:test.id,mode:'practice',submittedAt:now+offset,durationSec:95,answers,flags:{[qs[1].id]:true}});const attempts=[make('mixed',answers),make('final',full,-86400000),{...make('summary',{},-172800000),seedScore:{correct:5,total:6}},{...make('missing-question',{},-3000),testId:'old-bank',answers:{'missing-id':'x'}}];const manual=QUESTIONS.find(q=>q.kind==='written'&&!q.accepted.length);if(manual)attempts.push({...make('manual',{[manual.id]:'learner response'}),testId:'archived-manual'});return {attempts,qs,manual,session:{testId:'practice-1',mode:'practice',startedAt:now,endsAt:null,answers:{},flags:{},current:0}}}""")
 qs=fixture['qs'];attempts=fixture['attempts'];saved=[qs[1]['id'],qs[3]['id'],'missing-saved']
 seed={'hm.user':{'phone':'901234567','name':'','group':''},'hm.attempts':attempts,'hm.sessions':{'practice-1':fixture['session']},'hm.mistakes':saved,'hm.theme':'light'}
 page.evaluate('v=>{for(const[k,val]of Object.entries(v))localStorage.setItem(k,JSON.stringify(val));localStorage.setItem("hm.language","uz")}',seed)
 visit(page,'/results/mixed')
 check('Heading and visualization explicitly mark preliminary result','Dastlabki' in page.locator('h1').inner_text() and 'Dastlabki' in page.locator('svg[role=img]').get_attribute('aria-label'))
 check('Four verdict counts separate pending from mistakes',[page.locator('[data-verdict='+key+'] dd').inner_text() for key in ['correct','incorrect','unanswered','pending']]==['2','1','2','1'])
 expected=store(page,'attempts')
 pendingRadio=page.locator('.learning-answers [role=radio]').nth(3);pendingRadio.click();check('Pending filter is in URL and shows only pending row','filter=pending' in page.url and page.locator('.learning-question-link').count()==1)
 page.locator('.learning-question-link').click();check('Review keeps complete prompt and pending label',page.locator('main .body[lang=kaa]').count()>0 and page.locator('[data-pending]').count()==1)
 check('Review orders learner answer before expected model before explanation',page.locator('article h2').all_text_contents()[:3]==['Sizning javobingiz','Qabul qilinadigan javoblar','Izoh'])
 page.locator('.learning-head a').click();expect(page.locator('#result-question-4')).to_be_focused();check('Return restores filter and question focus','filter=pending' in page.url)
 page.locator('.learning-answers [role=radio]').nth(1).click();page.locator('.learning-question-link').click()
 page.keyboard.press('ArrowRight');page.wait_for_url('**/q/3?*');check('Review arrow navigation updates question without stacking history',True)
 page.go_back();page.wait_for_load_state('networkidle');check('Browser Back returns to filtered result after review steps','/results/mixed?filter=incorrect' in page.url)
 visit(page,'/results/mixed/q/2?return=https%3A%2F%2Fevil.example%2F');check('External return input cannot redirect learner',page.locator('.learning-head a').get_attribute('href')=='/results/mixed')
 page.evaluate('sessionStorage.setItem("fail-key","hm.mistakes")');button(page,'Saqlangan savollardan olib tashlash').click();check('Bookmark failure keeps saved list and shows actionable error',store(page,'mistakes')==saved and page.locator('[role=alert]').count()==1)
 page.evaluate('sessionStorage.removeItem("fail-key")');button(page,'Saqlangan savollardan olib tashlash').click();check('Bookmark removal persists only after successful write',qs[1]['id'] not in store(page,'mistakes'))
 button(page,'Savolni mashq uchun saqlash').click();check('Saving a review question does not alter its grade',store(page,'attempts')==expected and qs[1]['id'] in store(page,'mistakes'))
 page.get_by_role('link',name='Saqlangan savollarni ochish',exact=True).click();expect(page.locator('#saved-'+qs[1]['id'])).to_be_focused();check('Saved destination highlights requested question without opening answers',page.locator('.learning-retry').count()==0)
 first=page.locator('#saved-'+qs[1]['id']);first.locator('#retry-'+qs[1]['id']).click();expect(page.locator('#practice-heading-'+qs[1]['id'])).to_be_focused();check('Retry opens with no answer selected or explanation revealed',page.locator('.learning-retry .opt.sel').count()==0 and page.locator('.learning-retry .learning-explanation').count()==0)
 choice=qs[1]['correct'];page.locator('.learning-retry button.opt').nth(['A','B','C','D'].index(choice)).click();button(page,'Javobni tekshirish').click();check('Deliberate check reveals feedback and explanation',page.locator('.learning-retry .learning-explanation').count()==1 and page.locator('.learning-retry .opt.right').count()==1)
 button(page,'Qayta mashq qilish').click();check('Try again hides expected answer and clears choice',page.locator('.learning-retry .opt.right').count()==0 and page.locator('.learning-retry .opt.sel').count()==0 and page.locator('.learning-retry .learning-explanation').count()==0)
 page.keyboard.press('Escape');expect(first.locator('#retry-'+qs[1]['id'])).to_be_focused();check('Escape closes retry and restores invoking control',page.locator('.learning-retry').count()==0)
 written=page.locator('#saved-'+qs[3]['id']);written.locator('#retry-'+qs[3]['id']).click();check('Written retry does not expose accepted answers on open',page.locator('.learning-retry .learning-models').count()==0)
 page.locator('.learning-retry textarea').fill('Á ǵ ó ú ı ń');page.locator('.learning-retry textarea').focus();page.locator('.learning-retry .charbar button').first.click();check('Written retry preserves Karakalpak character insertion',page.locator('.learning-retry textarea').input_value().startswith('Á ǵ ó ú ı ń'))
 button(page,'Namunani ko‘rsatish').click();check('Written model appears only after deliberate reveal',page.locator('.learning-retry .learning-models').count()==1)
 check('Retries never mutate attempts or active sessions',store(page,'attempts')==expected and store(page,'sessions')=={'practice-1':fixture['session']})
 missing=page.locator('#saved-missing-saved');check('Missing saved ID stays visible and removable',missing.count()==1)
 missing.get_by_role('button').click();check('Removing unavailable saved entry is durable','missing-saved' not in store(page,'mistakes'))
 for path,to in [('/results/absent','/progress'),('/results/mixed/q/999','/results/mixed'),('/results/mixed/q/1.5','/results/mixed'),('/results/missing-question','/progress')]:
  visit(page,path);check('Named recovery '+path,page.locator('h1').inner_text()=='Kontent mavjud emas' and page.locator('main a').first.get_attribute('href')==to)
 visit(page,'/results/summary');check('Sample summary offers no invented review',page.locator('main h1').inner_text()=='Namuna natija xulosasi' and page.locator('main a[href*="/q/"]').count()==0)
 visit(page,'/results/final');check('Final result has explicit final heading and no pending warning',page.locator('h1').inner_text()=='Yakuniy natija' and page.locator('[data-pending]').count()==0)
 if fixture['manual']:
  visit(page,'/results/manual/q/1');check('Manual-only review declares absent model and disconnected grading',page.locator('.learning-models').count()==0 and page.locator('[data-pending]').count()==1)
 visit(page,'/progress');check('Final-only statistics exclude pending sample and missing content',page.locator('[data-average]').inner_text()=='100 foiz' and page.locator('[data-best]').inner_text()=='100 foiz')
 check('Chart exposes labeled axes and equivalent table',page.locator('.learning-y').inner_text().replace('\n','')=='100%50%0%' and page.locator('table caption').count()==1 and page.locator('table tbody tr').count()==len(attempts))
 check('Pending history row remains preliminary',page.locator('tr[data-attempt=mixed][data-pending] .tag').inner_text()=='Dastlabki natija')
 check('Sample history has no broken result link',page.locator('tr[data-attempt=summary] a').count()==0)
 page.locator('main [role=radio]').nth(1).click();page.locator('tr[data-attempt=final] a').click();page.locator('.learning-head a').click();check('History mode survives result return','/progress?mode=practice' in page.url)
 page.locator('main [role=radio]').nth(2).click();check('No matches differs from empty history and resets',page.locator('h2').inner_text()=='Bu rejimda urinishlar yo‘q');button(page,'Barcha urinishlarni ko‘rsatish').click()
 visit(page,'/profile');check('Profile excludes internal demo and design operations',page.locator('main a[href="/design"],main a[href^="/admin"]').count()==0)
 page.evaluate('sessionStorage.setItem("fail-key","hm.theme")');page.locator('main [role=radio]').nth(2).click();check('Failed theme change reports failure and preserves selected value',store(page,'theme')=='light' and page.locator('main [role=radio]').nth(1).get_attribute('aria-checked')=='true' and page.locator('[role=alert]').count()==1)
 page.evaluate('sessionStorage.removeItem("fail-key")');button(page,'Saqlashni qayta urinish').click();check('Preference retry applies and persists intended value',store(page,'theme')=='dark')
 page.locator('[role=switch]').click();check('Reduced transparency preference persists',store(page,'rt')==True)
 page.evaluate('sessionStorage.setItem("fail-key","hm.language")');page.locator('main select').select_option('ru');check('Language failure reports tab-only change',page.locator('main [role=alert]').count()==1 and page.locator('main h1').inner_text()=='Профиль')
 page.evaluate('sessionStorage.removeItem("fail-key")');button(page,'Повторить сохранение').click();page.reload();page.wait_for_load_state('networkidle');check('Language appearance and accessibility restore after reload',page.locator('main h1').inner_text()=='Профиль' and page.locator('html').get_attribute('class').find('rt-on')>=0 and store(page,'theme')=='dark')
 page.locator('main select').select_option('uz');button(page,'Chiqish').click();expect(page.locator('#keep-signed-in')).to_be_focused();page.keyboard.press('Escape');check('Active-work sign-out supports safe focus and cancellation',store(page,'user') is not None and page.locator('dialog[open]').count()==0)
 button(page,'Chiqish').click();page.evaluate('sessionStorage.setItem("fail-remove","hm.user")');page.locator('dialog').get_by_role('button',name='Chiqish',exact=True).click();check('Sign-out failure retains identity and offers retry',store(page,'user') is not None and page.locator('dialog [role=alert]').count()==1)
 page.evaluate('sessionStorage.removeItem("fail-remove")');page.locator('dialog').get_by_role('button',name='Chiqish',exact=True).click();page.wait_for_url('**/sign-in');check('Confirmed sign-out keeps browser work without fabricated account isolation',store(page,'user') is None and store(page,'attempts')==expected and store(page,'sessions')=={'practice-1':fixture['session']})
 page.evaluate('localStorage.setItem("hm.user",JSON.stringify({phone:"901234567"}));localStorage.setItem("hm.attempts","[]");localStorage.setItem("hm.mistakes","[]")');visit(page,'/progress');check('Empty progress invents no chart history',page.locator('table').count()==0 and page.locator('.learning-chart').count()==0)
 visit(page,'/mistakes');check('Empty saved list explains how to save questions',page.locator('.saved-question').count()==0 and page.locator('main a[href="/tests?mode=practice"]').count()==1)
 check('No unexpected JavaScript errors',not errors)
 c.close();b.close()
(OUT/'journey-results.json').write_text(json.dumps(checks,ensure_ascii=False,indent=2),encoding='utf-8')
assert all(row['passed'] for row in checks)
